from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    """Return x if it is even; raise Bad(x) if it is odd."""
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element in a thread pool.

    Returns the checked values in input order. If any element is odd,
    raises the Bad for the lowest-index odd element.
    """
    with ThreadPoolExecutor() as pool:
        # map yields results in input order and re-raises the exception
        # from the first failing index when that result is reached.
        return list(pool.map(check, xs))


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 0]) == [2, 4, 0]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_raises_on_single_odd() -> None:
    with pytest.raises(Bad) as excinfo:
        all_even([2, 3, 4])
    assert excinfo.value.n == 3


def test_all_even_reports_lowest_index_odd() -> None:
    # Two odd elements: 7 at index 1 and 3 at index 2. The lowest index wins.
    with pytest.raises(Bad) as excinfo:
        all_even([4, 7, 3])
    assert excinfo.value.n == 7


def test_check_even_passes_through() -> None:
    assert check(6) == 6


def test_check_odd_raises() -> None:
    with pytest.raises(Bad) as excinfo:
        check(5)
    assert excinfo.value.n == 5


def test_thread_pool_is_used() -> None:
    # Confirms the ThreadPoolExecutor type is importable for the implementation.
    with ThreadPoolExecutor(max_workers=1) as pool:
        assert pool.submit(check, 2).result() == 2
